import * as zlib from 'node:zlib';
function main(): void {
  const z: any = zlib;
  console.log(z.constants.Z_MAX_CHUNK, typeof z.constants.Z_MAX_CHUNK, z.constants.Z_DEFAULT_CHUNK);
  const g: any = z.createGzip();
  g.write('hello');
  console.log(g.bytesWritten, g.bytesRead);
  g.destroy();
}
